	| "begin-conflict"
	| "begin-malformed"
	| "begin-unavailable"
	| "commit-conflict"
	| "commit-malformed"
	| "commit-unavailable-once"
	| "create-conflict"
	| "create-malformed"
	| "create-unavailable"
	| "none"
	| "read-malformed"
	| "read-unavailable";

